/// Run-length encodes `s`: each run becomes the character followed by its length.
pub fn rle(s: Str) -> Str {
  var out = ""
  var cur = ""
  var n = 0
  for c in s.chars() {
    if c == cur {
      n = n + 1
    } else {
      if n > 0 {
        out = out + cur + n.to_str()
      }
      cur = c
      n = 1
    }
  }
  if n > 0 {
    out = out + cur + n.to_str()
  }
  return out
}
